	import React, { useEffect, useState } from "react";
import api from "../services/api";

const LogsWidget = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  // Function to fetch server logs
  const fetchLogs = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        setError("Unauthorized: Please log in.");
        setLoading(false);
        return;
      }

      const response = await api.get("/api/auth/metrics/", {
        headers: {
          Authorization: `Token ${token}`,
          "Content-Type": "application/json",
        },
      });

      console.log("Fetched Logs Data:", response.data);

      if (response.data.length > 0) {
        setLogs(response.data);
        setLoading(false);
      } else {
        setError("No logs available.");
        setLoading(false);
      }
    } catch (err) {
      console.error("Error fetching logs:", err);
      setError("Failed to fetch logs.");
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchLogs();
    const interval = setInterval(fetchLogs, 10000); // Refresh logs every 10 sec
    return () => clearInterval(interval);
  }, []);

  return (
    <div
      style={{
        flex: "1",
        padding: "1.5rem",
        backgroundColor: "#fff",
        borderRadius: "8px",
        boxShadow: "0 2px 8px rgba(0, 0, 0, 0.1)",
        maxHeight: "300px",
        overflowY: "auto",
      }}
    >
      <h3>Server Logs</h3>
      {loading ? <p>Loading...</p> : error ? <p>{error}</p> : null}
      <button onClick={fetchLogs} style={{ marginBottom: "10px" }}>
        Refresh Logs
      </button>
      <details className="mt-2">
              <summary>View Logs</summary>
              <ul>
                {JSON.parse(metric.logs).map((log, logIndex) => (
                  <li key={logIndex}>{log}</li>
                ))}
              </ul>
       </details>
    </div>
  );
};

export default LogsWidget;
